from pathlib import Path
import re
root=Path(__file__).resolve().parent.parent
base=(root/'scripts/home-template.html').read_text()
header=re.search(r'<header>.*?</header>',base).group();footer=re.search(r'<footer>.*?</footer>',base).group();dialog=re.search(r'<dialog.*?</dialog>',base).group()
